int opposite(int face) {
    switch (face) {
        case 0: return 5;
        case 1: return 3;
        case 2: return 4;
        case 3: return 1;
        case 4: return 2;
        case 5: return 0;
    }
    return -1;
}

int max_side(int u, int d) {
    if (u != 6 && d != 6) return 6;
    if (u != 5 && d != 5) return 5;
    return 4;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int dice[1005][6];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 6; j++) {
            scanf("%d", &dice[i][j]);
        }
    }

    int best_total = 0;

    // Tentamos cada uma das 6 faces como face superior do primeiro dado
    for (int top_face_idx = 0; top_face_idx < 6; top_face_idx++) {
        int current_sum = 0;
        int top_val = dice[0][top_face_idx];
        int bottom_val = dice[0][opposite(top_face_idx)];

        current_sum += max_side(top_val, bottom_val);

        // Para os dados seguintes
        for (int i = 1; i < n; i++) {
            int bot_idx = -1;
            for (int j = 0; j < 6; j++) {
                if (dice[i][j] == top_val) {
                    bot_idx = j;
                    break;
                }
            }
            int top_idx = opposite(bot_idx);
            bottom_val = dice[i][bot_idx];
            top_val = dice[i][top_idx];

            current_sum += max_side(top_val, bottom_val);
        }

        if (current_sum > best_total) {
            best_total = current_sum;
        }
    }

    printf("%d\n", best_total);

    return 0;
}
